  {
    name: 'Target',
    type: 'line',
    data: targetData,
    lineStyle: { color: '#999', width: 1, type: 'dashed' },
    itemStyle: { color: '#999' },
    showSymbol: false,
    endLabel: {
      show: true,
      formatter: '{a}: {c}',
      fontSize: 13,
      fontFamily: '"ET Book", Palatino, Georgia, serif',
      color: '#999',
    },
  },
]
```

## Annotations via markPoint / markLine

```typescript
series: [{
  // ... base config
  markPoint: {
    data: [
      { type: 'max', name: 'Peak' },
    ],
    symbol: 'circle',
    symbolSize: 6,
    label: {
      show: true,
      position: 'top',
      formatter: 'Peak: {c}',
      fontSize: 12,
      fontStyle: 'italic',
      color: '#333',
      fontFamily: '"ET Book", Palatino, Georgia, serif',
    },
    itemStyle: { color: '#e41a1c' },
  },
  markLine: {
    data: [
      { type: 'average', name: 'Avg' },
    ],
    lineStyle: { color: '#ccc', width: 0.5, type: 'dashed' },
    label: {
      position: 'end',
      formatter: 'Avg: {c}',
      fontSize: 11,
      color: '#999',
    },
  },
}]
```

## Range-frame via axis min/max

```typescript
// Compute from data
const values = data.flat();
const dataMin = Math.min(...values);
const dataMax = Math.max(...values);
const padding = (dataMax - dataMin) * 0.05;

yAxis: {
  min: dataMin - padding,
  max: dataMax + padding,
}
```

